"""Run the selected learned controller with its declared physics and reference settings."""
from pathlib import Path
import json,sys,importlib.util,hashlib
R=Path(__file__).resolve().parents[1];BASE=R.parents[1];sys.path.insert(0,str(BASE))
from batch_native import docker,containers
c=json.loads((R/'episode-config.json').read_text());runtime=json.loads((R/'runtime-config.json').read_text());newton=c.get('native_container') or containers(R,c['episode'])[0];gain=runtime['inference']['wrist_reference_velocity_gain'];substeps=runtime['inference']['physics_substeps'];reference=runtime['inference']['reference'];checkpoint=runtime['checkpoint'];state='/episode/evaluation/reproduced-policy-states.npz';record='record_velocity_controller.py' if gain else 'record_policy_states.py'
spec=runtime['inference'].get('robot_release_controller_spec');record='record_hybrid_controller.py' if spec else record
if runtime.get('checkpoint_sha256'):assert hashlib.sha256((R/checkpoint.removeprefix('/episode/')).read_bytes()).hexdigest()==runtime['checkpoint_sha256'],'Selected policy changed'
if runtime['inference'].get('reference_parquet_sha256'):assert hashlib.sha256(next((R/f'human_motion_data/{reference}/processed').rglob('motion.parquet')).read_bytes()).hexdigest()==runtime['inference']['reference_parquet_sha256'],'Inference reference changed'
docker(['exec',newton,'env',f'V2D_WRIST_VELOCITY_GAIN={gain}',*([f'V2D_RELEASE_SPEC={json.dumps(spec)}'] if spec else []),f'V2D_STATE_OUTPUT={state}','python','-u',f'/episode/scripts/{record}',f'evaluation.checkpoint={checkpoint}',f'sim.substeps={substeps}',f"task.parquet='/episode/human_motion_data/{reference}/processed/sequence_id={c['sequence']}/robot_name=sharpa_wave'",'viewer.backend=none','hydra.run.dir=/episode/hydra/reproduce-selected-policy'],R/'logs/reproduce-selected-policy.log')
docker(['exec',newton,'env',f'V2D_REPLAY_STATE_FILE={state}','V2D_STATE_OUTPUT=/episode/evaluation/reproduced-render-states.npz','python','-u','/episode/scripts/render_source_camera.py',f'evaluation.checkpoint={checkpoint}','viewer.backend=mp4','viewer.width=1024','viewer.height=768',f"viewer.num_frames={(c['frames'] if c.get('validated_video_pipeline') else 2*(c['frames']-1))}",'viewer.video_fps=20','viewer.realtime=false','markers.enabled=false','viewer.output_path=/episode/videos/reproduced_policy_native_timing.mp4','hydra.run.dir=/episode/hydra/reproduce-selected-render'],R/'logs/reproduce-selected-render.log')
print(R/'videos/reproduced_policy_native_timing.mp4');print('Native half-speed timing. Contact simulation can vary; published videos replay the exact recorded selected attempt.')
